import ghidra.app.script.GhidraScript;import java.nio.file.*;public class MatrixUsers extends GhidraScript {public void run() throws Exception {StringBuilder b=new StringBuilder();for(int i=1;i<getScriptArgs().length;i++){var a=toAddr(getScriptArgs()[i]);for(var ref:getReferencesTo(a)){var f=getFunctionContaining(ref.getFromAddress());b.append(a+"\t"+ref.getFromAddress()+"\t"+(f==null?"none":f.getEntryPoint())+"\n");}}Files.writeString(Path.of(getScriptArgs()[0]),b.toString());}}